svg.script:
(function () {
  var svg = document.currentScript ? document.currentScript.closest('svg') : document.documentElement;
  if (!svg) svg = document.documentElement;
  var segue = svg.querySelector('.segue');
  var olhos = svg.querySelector('.olhos');
  var centro = { x: 1180, y: 610 }, max = 90, timer;
  window.addEventListener('mousemove', function (ev) {
    var m = svg.getScreenCTM(); if (!m) return;
    var p = new DOMPoint(ev.clientX, ev.clientY).matrixTransform(m.inverse());
    var dx = p.x - centro.x, dy = p.y - centro.y, d = Math.hypot(dx, dy) || 1;
    var k = Math.min(1, d / 900) * max;
    segue.setAttribute('transform', 'translate(' + (dx / d * k).toFixed(1) + ' ' + (dy / d * k * 0.7).toFixed(1) + ')');
    if (olhos) olhos.style.animationPlayState = 'paused';
    clearTimeout(timer);
    timer = setTimeout(function () {
      segue.setAttribute('transform', 'translate(0 0)');
      if (olhos) olhos.style.animationPlayState = '';
    }, 2500);
  });
})();
